bool mdit_case_fold_lookup(uint32_t cp, const char **out, size_t *len)
{
    size_t lo = 0, hi = 1531;
    while (lo < hi) {
        size_t mid = lo + ((hi - lo) >> 1);
        uint32_t mcp = k_case_fold_table[mid].cp;
        if (mcp < cp) lo = mid + 1;
        else if (mcp > cp) hi = mid;
        else {
            *out = k_case_fold_pool + k_case_fold_table[mid].off;
            *len = k_case_fold_table[mid].len;
            return true;
        }
    }
    return false;
}
